const body = $json || {};
const messageId = String(body.messageId || body.id || '');
const from = String(body.from || body.userId || '');
const text = String(body.text || body.body || '').trim();
const type = String(body.type || 'text');
const payload = {
  messageId,
  from,
  type,
  text,
  mediaPath: body.mediaPath || undefined,
  languageHint: body.languageHint || undefined,
  timestamp: body.timestamp || Date.now()
};

if (!payload.messageId || !payload.from) {
  return [{ json: { deduped: false, replyText: 'Invalid inbound payload', session: null } }];
}

const sessionApi = 'http://session-api:4000';

const dedupeResp = await fetch(`${sessionApi}/dedupe/${encodeURIComponent(payload.messageId)}`, {
  method: 'POST'
});
if (!dedupeResp.ok) {
  throw new Error(`dedupe failed: ${dedupeResp.status} ${dedupeResp.statusText}`);
}
const dedupeData = await dedupeResp.json();
if (dedupeData.deduped) {
  return [{ json: { deduped: true, replyText: '', session: null } }];
}

const sessionResp = await fetch(`${sessionApi}/session/${encodeURIComponent(payload.from)}`);
let session;
if (sessionResp.status === 404) {
  session = { userId: payload.from, step: 0, state: {} };
} else if (sessionResp.ok) {
  const sessionData = await sessionResp.json();
  session = sessionData.session || { userId: payload.from, step: 0, state: {} };
} else {
  throw new Error(`session lookup failed: ${sessionResp.status} ${sessionResp.statusText}`);
}

let step = Number(session.step ?? 0);
const state = { ...(session.state || {}) };
let replyText = '';

if (step === 0) {
  replyText = 'Hi! Welcome to onboarding. What is your full name?';
  step = 1;
} else if (step === 1) {
  state.fullName = text;
  replyText = 'Thanks. Which language would you like to continue in?';
  step = 2;
} else if (step === 2) {
  state.language = text;
  replyText = 'Great. Please share your email address.';
  step = 3;
} else if (step === 3) {
  state.email = text;
  replyText = 'What service are you interested in?';
  step = 4;
} else if (step === 4) {
  state.service = text;
  replyText = 'Thanks — your onboarding is complete.';
  step = 5;
} else {
  replyText = 'You are already onboarded. Reply HELP for support.';
}

const nextSession = { userId: payload.from, step, state };
const saveResp = await fetch(`${sessionApi}/session/${encodeURIComponent(payload.from)}`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ step: nextSession.step, state: nextSession.state })
});
if (!saveResp.ok) {
  throw new Error(`session save failed: ${saveResp.status} ${saveResp.statusText}`);
}

return [{ json: { deduped: false, replyText, session: nextSession } }];
